-- Remus · Handover 6: A YEAR OF MADE-UP JOBS (Stephan, 31 Oct 2026: "put in more data ... fake data. For the
-- last year ... four projects run every month"). Every row it adds is listed in public.demo_rows.
-- Generated by plan.py (job and stage dates); everything else is worked out here.
create temp table sj (key text, n int, kind text, status text, factor numeric, start_d date, end_d date, name text, first text, last text, site text, pid uuid, cid uuid);
create temp table ss (key text, ord int, section text, start_d date, end_d date, mat numeric, sub numeric, trade text);
do $seed$
declare
  admin uuid := 'cfafe573-fffb-445f-879f-90b44f7bb5a4';
  today date := '2026-10-31';
  yday date := '2026-10-30';
  j record; s record; w record;
  v_pid uuid; v_cid uuid; v_qid uuid; v_sid uuid; v_inv uuid; v_id uuid;
  qn int := 9000; inv_n int := 9000; code_n int := 100;
  v_sell numeric; v_cost numeric; v_total numeric; p numeric; amt numeric; d date; i int;
  senior uuid; junior uuid; k int := 0;
  suppliers text[] := array['Cashbuild','Builders','BUCO','Leroy Merlin','Build It','Plumblink','Cashbuild','Builders'];
  weathers text[] := array['Sunny','Sunny, hot','Partly cloudy','Overcast','Afternoon thunderstorm','Clear and windy'];
begin
  -- Workers
  create temp table sw (id uuid, name text, trade text, grade text, cost numeric) on commit drop;

  for j in select * from sj order by n loop
    -- the client
    v_cid := j.cid;
    if v_cid is null and j.pid is null then
      values (j.first, j.last, lower(j.first)||'.'||lower(replace(j.last,' ',''))||'@example.co.za',
              '08'||(2+(j.n%5))||' '||lpad(((j.n*7919)%1000)::text,3,'0')||' '||lpad(((j.n*104729)%10000)::text,4,'0'), j.site, admin, admin)
      returning id into v_cid;
    end if;

    -- the project
    if j.pid is not null then
      v_pid := j.pid;
      update projects set start_date = j.start_d, end_date = j.end_d, status = j.status where id = v_pid;
      if v_cid is null then select contact_id into v_cid from projects where id = v_pid; end if;
    else
      code_n := code_n + 1;
      values (j.name, 'UHG-'||code_n, v_cid, j.site, j.status, j.start_d, j.end_d, 0, 0, admin, admin) returning id into v_pid;
    end if;

    -- the quote (Smith keeps Q-0001; Centurion keeps its own Q-0002)
    v_qid := null;
    if j.key not in ('smith','centurion') then
      qn := qn + 1;
                          show_plan, sent_at, sent_to, approved_at, approved_by, owner_id, created_by, scope, terms)
      values ('Q-'||qn, v_cid, v_pid, coalesce(j.name, (select name from projects where id=v_pid)), coalesce(j.site,(select site_address from projects where id=v_pid)),
              'accepted', j.start_d - 24, j.start_d + 6, 0, 5, 50, true, (j.start_d - 23)::timestamptz + interval '9 hours',
              'client', (j.start_d - 24)::timestamptz + interval '15 hours', admin, admin, admin,
              'Complete ' || lower(coalesce(j.name,'job')) || ' as discussed on site, materials and labour included.',
              '50% deposit on acceptance, 30% at the halfway mark, the balance on completion.')
      returning id into v_qid;
      i := 0;
      for s in select * from ss where key = j.key order by ord loop
        if s.sub > 0 then
        end if;
        values (v_qid, s.section, s.ord, greatest(1,(select count(*) from generate_series(s.start_d, s.end_d, '1 day') g where extract(isodow from g) < 6)),
                case when s.ord = 0 then 'start' else 'after' end, (select section from ss x where x.key=j.key and x.ord = s.ord-1), 0);
        i := i + 4;
      end loop;
      select sum(quantity*unit_price), sum(quantity*unit_cost) into v_sell, v_cost from quote_items where quote_id = v_qid;
      v_total := round(v_sell * 1.05, 2);
      update quotes set approved_total = v_total where id = v_qid;
      update projects set quote_id = v_qid, contract_value = v_total, budget = round(v_cost,2) where id = v_pid;
    end if;

    -- the plan's stages, the crew, the slips
    for s in select * from ss where key = j.key order by ord loop
      values (v_pid, s.section, s.ord, s.start_d, s.end_d, round((s.mat*1.25 + s.sub*1.2),2), s.mat,
              case when j.key = 'smith' then 0 else 1030 * greatest(1,(select count(*) from generate_series(s.start_d, s.end_d, '1 day') g where extract(isodow from g) < 6)) end, s.sub)
      returning id into v_sid;

      -- how far the stage is: done, under way (by days), or not started
      p := case when s.end_d <= yday then 1 when s.start_d > yday then 0
                else (yday - s.start_d + 1)::numeric / (s.end_d - s.start_d + 1) end;

      -- the crew: a senior of the trade and a junior, for running and coming jobs
      if j.status in ('active','planned') then
        k := k + 1;
        select id into senior from sw where trade = s.trade and grade = 'senior' order by name limit 1;
        if senior is null then select id into senior from sw where grade = 'senior' order by name offset (k % 6) limit 1; end if;
        select id into junior from sw where grade = 'junior' order by name offset (k % 4) limit 1;
        if junior <> senior then
        end if;
        -- the register: what happened, up to yesterday
        if j.status = 'active' then
          select w2.id, v_pid, v_sid, g::date, case when random() < 0.06 then 0.5 else 1 end, w2.cost, admin
            from generate_series(s.start_d, least(s.end_d, yday), '1 day') g
            cross join sw w2
           where w2.id in (senior, junior) and extract(isodow from g) < 6
          on conflict do nothing;
        end if;
      end if;

      -- slips: materials in two buys, the subcontractor, and (finished jobs) the weekly wages
      if p > 0 and j.key <> 'smith' then
        amt := round(s.mat * j.factor * p, -1);
        values (v_pid, v_sid, s.start_d, 'materials', suppliers[1 + (j.n + s.ord) % 8], s.section || ' materials', round(amt*0.6,2), 0, true, 'manual', admin),
               (v_pid, v_sid, s.start_d + least(3, s.end_d - s.start_d), 'materials', suppliers[1 + (j.n + s.ord + 3) % 8], s.section || ' materials (top-up)', round(amt*0.4,2), 0, true, 'manual', admin);
        if s.sub > 0 then
          values (v_pid, v_sid, least(s.end_d, yday), 'subcontractor', s.section || ' specialists', s.section || ': subcontractor''s invoice', round(s.sub * j.factor * p, -1), 0, p = 1, 'manual', admin);
        end if;
        if j.status = 'completed' then
          values (v_pid, v_sid, s.end_d, 'labour', 'Wages', s.section || ': crew wages', round(1030 * j.factor * greatest(1,(select count(*) from generate_series(s.start_d, s.end_d, '1 day') g where extract(isodow from g) < 6)), -1), 0, true, 'manual', admin);
        end if;
      end if;

      -- the site diary: a finished job's first and last day of each stage; a running job every working day lately
      for d in select g::date from generate_series(s.start_d, least(s.end_d, case when j.key in ('smith','naidoo') then today else yday end), '1 day') g
               where (extract(isodow from g) < 6 or g::date = today)
                 and (j.status = 'active' and g >= today - 16 or g::date in (s.start_d, s.end_d)) loop
        values (v_pid, d, weathers[1 + (extract(doy from d)::int % 6)], case when d = today then 2 else 2 + (extract(doy from d)::int % 3) end,
          case when d = s.start_d then 'Started ' || lower(s.section) || '. Set out and prepared the area.'
               when d = s.end_d then lower(initcap(s.section)) || ' finished and checked. Area cleaned for the next stage.'
               when d = today then 'Saturday half day: ' || lower(s.section) || ' carried on, site tidied and locked up.'
               else initcap(s.section) || ' under way: about ' || round(100.0 * (d - s.start_d + 1) / (s.end_d - s.start_d + 1)) || '% of this stage done.' end,
          case when d = s.start_d and s.mat > 0 then s.section || ' materials delivered from ' || suppliers[1 + (j.n + s.ord) % 8] end,
          case when weathers[1 + (extract(doy from d)::int % 6)] = 'Afternoon thunderstorm' then 'Rain stopped outside work at 14:30.' end,
          admin)
        on conflict (project_id, date) do nothing
        returning id into v_id;
        if v_id is not null then insert into demo_rows values ('site_diary_entries', v_id) on conflict do nothing; end if;
        v_id := null;
      end loop;
    end loop;

    -- invoices: deposit at the start, 30% halfway, the rest at the end
    if v_qid is not null and j.status in ('completed','active') then
      select contract_value into v_total from projects where id = v_pid;
      for i in 1..3 loop
        d := case i when 1 then j.start_d - 3 when 2 then j.start_d + (j.end_d - j.start_d) / 2 else j.end_d end;
        continue when d > yday;
        inv_n := inv_n + 1;
        values (v_pid, v_cid, 'INV-'||inv_n, d, d + 7,
                case i when 1 then 'Deposit (50%)' when 2 then 'Progress payment (30%)' else 'Final payment (20%)' end,
                round(v_total * case i when 1 then 0.5 when 2 then 0.3 else 0.2 end, 2), 0,
                case when d + 7 < yday or i = 1 then 'paid' else 'sent' end, admin)
        returning id into v_inv;
        if d + 7 < yday or i = 1 then
          values (v_inv, v_pid, least(d + 5, yday), round(v_total * case i when 1 then 0.5 when 2 then 0.3 else 0.2 end, 2), 'eft', 'INV-'||inv_n, admin)
          returning id into v_id;
        end if;
      end loop;
    end if;

    -- coming up in the diary
    if j.status = 'planned' then
      values ('Pre-start site meeting: ' || coalesce(j.name, (select name from projects where id=v_pid)), (j.start_d - 3)::timestamptz + interval '8 hours',
              (j.start_d - 3)::timestamptz + interval '9 hours', v_pid, v_cid, 'site_visit', coalesce(j.site,(select site_address from projects where id=v_pid)),
              'Walk the site with the client, agree access and where materials go.', admin, admin)
      returning id into v_id;
    end if;
  end loop;

  -- deliveries and an inspection next week, on the running jobs
  select x.t, x.at, x.at + interval '1 hour', p.id, x.ty, p.site_address, x.nt, admin, admin
    from (values
      ('UHG-002', 'Tiles delivery (Naidoo)', timestamptz '2026-11-02 08:00+02', 'delivery', 'Floor and wall tiles from Leroy Merlin.'),
      ('UHG-002', 'Plumbing inspection (Naidoo)', timestamptz '2026-11-04 10:00+02', 'inspection', 'Pressure test before the walls are closed.'),
      ('UHG-001', 'Kitchen cabinets delivered (Smith)', timestamptz '2026-11-03 09:00+02', 'delivery', 'Cabinets and tops from the joiner.'),
      ('UHG-001', 'Client walk-through (Smith)', timestamptz '2026-11-06 15:00+02', 'site_visit', 'Show Mr Smith the bathrooms; agree the patio paving colour.')
    ) as x(code, t, at, ty, nt)
    join projects p on p.code = x.code;
end
$seed$;

